using System.Collections.Generic;using Janseon.Core.Data;using Janseon.Data.Validation;
namespace Janseon.Data.Repositories { public sealed class CardCatalogRepository:IReadOnlyCardCatalog { readonly Dictionary<string,CardCatalogItem> byId=new Dictionary<string,CardCatalogItem>(System.StringComparer.Ordinal);readonly Dictionary<string,CardCatalogItem> byCore=new Dictionary<string,CardCatalogItem>(System.StringComparer.Ordinal);public IReadOnlyList<CardCatalogItem> All{get;} public CardCatalogRepository(GameDataCatalogIndex i){All=i.Cards;foreach(var x in All){byId.Add(x.StableId,x);byCore.Add(x.CoreCardId,x);}}public bool TryGet(string id,out CardCatalogItem x)=>byId.TryGetValue(id??string.Empty,out x);public bool TryGetByCoreId(string id,out CardCatalogItem x)=>byCore.TryGetValue(id??string.Empty,out x);}}
